import{_ as t,a as e,b as i,c as r,d as o}from"./chunks/CAL20.BDesHKIj.js";import{_ as l,o as n,c as s,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const _=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"calibrate/troubleshoot.md","filePath":"calibrate/troubleshoot.md"}'),c={name:"calibrate/troubleshoot.md"};function b(h,a,p,m,f,u){return n(),s("div",null,[...a[0]||(a[0]=[d('<h3 id="native-algorithm" tabindex="-1">Native Algorithm <a class="header-anchor" href="#native-algorithm" aria-label="Permalink to &quot;Native Algorithm&quot;">​</a></h3><p>If you use xDrip with a G6, G7, 1, 1+ or Stelo native algorithm, see <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">here</a>.</p><h3 id="xdrip-algorithm" tabindex="-1">xDrip Algorithm <a class="header-anchor" href="#xdrip-algorithm" aria-label="Permalink to &quot;xDrip Algorithm&quot;">​</a></h3><p>Enable <a href="./../use/lesscommon.html#show-data-tables">data tables</a> for more information.</p><h4 id="no-data-after-initial-calibration" tabindex="-1">No data after initial calibration <a class="header-anchor" href="#no-data-after-initial-calibration" aria-label="Permalink to &quot;No data after initial calibration&quot;">​</a></h4><img src="'+t+'" style="zoom:75%;"><p>If you checked you have connectivity with sensor/bridge and no data shows up after initial calibration, it might be because you&#39;re calibrating too high and the intercept calculated is above safety limit. <a href="./calibrate.html#reset-all-calibrations">Reset</a> all calibrations and retry at stable BG when in the lower range.</p><h4 id="no-data-after-adding-a-new-calibration" tabindex="-1">No data after adding a new calibration <a class="header-anchor" href="#no-data-after-adding-a-new-calibration" aria-label="Permalink to &quot;No data after adding a new calibration&quot;">​</a></h4><img src="'+e+'" style="zoom:75%;"><p>You probably drove calibrations out of safety limits. Check Calibration Data Table and, if needed, <a href="./calibrate.html#disable-a-calibration">disable</a> the offending calibration.</p><p>A sensor requiring a large positive intercept might not be safe. If you believe your sensor is still reliable <a href="./calibrate.html#reset-all-calibrations">Reset</a> all calibrations and retry at stable BG when in the lower range.</p><h4 id="new-calibration-is-ignored" tabindex="-1">New calibration is ignored <a class="header-anchor" href="#new-calibration-is-ignored" aria-label="Permalink to &quot;New calibration is ignored&quot;">​</a></h4><img src="'+i+'" style="zoom:75%;"><p>Check Calibration Data Table and you will most probably see your calibrations displayed in red as they are disabled for safety reasons.</p><p>Most probably your sensor isn&#39;t reliable anymore. If you believe it is, <a href="./calibrate.html#reset-all-calibrations">Reset</a> all calibrations and retry at stable BG when in the lower range.</p><h4 id="intercept-or-slope-above-safety-limit" tabindex="-1">Intercept or slope above safety limit <a class="header-anchor" href="#intercept-or-slope-above-safety-limit" aria-label="Permalink to &quot;Intercept or slope above safety limit&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Safety</p><p>Limits preventing you from calibrating are designed for your own safety.<br><strong>You cannot rely on a system that is not able to detect hypoglycemia.</strong></p></div><p>Open your Calibration Data Table and check last calibration.</p><img src="'+r+'" style="zoom:75%;"><div class="warning custom-block"><p class="custom-block-title">Maximum authorized intercept is 39</p><p>An intercept above 39 mg/dl will prevent BG display for safety reasons.</p></div><p>Slope limits depend on your sensor:</p><table tabindex="0"><thead><tr><th>Sensor</th><th>Minimum slope</th><th>Maximum slope</th></tr></thead><tbody><tr><td>G5 or G6 non-native algorithm (3+ calibrations)</td><td>0.7</td><td>1.6</td></tr><tr><td>G5 or G6 non-native algorithm (exactly 2 calibrations)</td><td>0.75</td><td>1.5</td></tr><tr><td>Libre (raw data source, Non-fixed Libre Slopes enabled)</td><td>0.5</td><td>1.6</td></tr><tr><td>Libre (raw data source, default fixed slope)</td><td>1 (fixed)</td><td>1 (fixed)</td></tr><tr><td>Libre 2 patched app</td><td>1 (fixed)</td><td>1 (fixed)</td></tr></tbody></table><p>Since slope and intercept safety limits will prevent xDrip from having a too high intercept, calibrations leading to this situation will be ignored.</p><p>In the example below you see the orange line is the one that best matches the calibrations; still, xDrip will use the red one for safety as its intercept is safe. You can see the plugin intercept value reflecting what would better match calibrations.</p><img src="'+o+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Last modified 7/12/2024</em></a></p>',27)])])}const v=l(c,[["render",b]]);export{_ as __pageData,v as default};
